sql.where:
      i.is_deleted = false AND d.is_deleted = false

      
      
        AND i.shop_id = #{currentUserShopId}
      

      
      
        AND i.shop_id = #{shopId}
      

      
      
        AND i.invoice_id = #{invoiceId}::uuid
      

      
      
        AND i.created_at >= #{startDateTime}
      
      
        AND i.created_at <= #{endDateTime}
      

      
      
        AND (
        d.drink_name ILIKE '%' || #{search} || '%'
        OR p.full_name ILIKE '%' || #{search} || '%'
        OR s.shop_name ILIKE '%' || #{search} || '%'
        OR CAST(i.table_number AS VARCHAR) ILIKE '%' || #{search} || '%'
        OR CAST(i.invoice_id AS VARCHAR) ILIKE '%' || #{search} || '%'
        )

mapper.select:
ORDER BY
i.invoice_id s.shop_name p.full_name d.drink_name i.created_at i.total_amount i.table_number id.quantity id.unit_price i.created_at
${sortDirection}
LIMIT #{size} OFFSET #{offset}
